// Общие шаги для «העדפות חיפוש» (#3872fc): открыть экран, прочитать метки ползунка возраста, перетащить ручку.
// У ползунка нет ролей/подписей доступности — метки и ручки находятся по тексту и геометрии (шкала «20 … 60+»).
import { expect, type Page } from '@playwright/test';

export const PREFS_URL = '/prefs?from=settings';

export async function openPrefs(page: Page) {
  await page.goto(PREFS_URL);
  await expect(page.getByText('העדפות חיפוש')).toBeVisible();
  await expect(page.getByText('גיל', { exact: true })).toBeVisible();
  await expect(page.getByRole('button', { name: 'שמירה' })).toBeVisible();
  // Значения приходят из профиля после отрисовки — ждём, пока метки возраста перестанут меняться.
  let prev = '';
  await expect
    .poll(async () => {
      const cur = JSON.stringify(await ageGeometry(page).then((g) => g.labels.map((l) => [l.v, Math.round(l.x)])));
      const stable = cur === prev && cur !== '[]';
      prev = cur;
      return stable;
    }, { intervals: [300, 300, 500] })
    .toBe(true);
}

type Geo = { labels: { v: string; x: number; y: number }[]; x20: number; x60: number; trackY: number };

// Метки значений над ручками (две) и позиции делений «20» и «60+» шкалы возраста — в блоке между «גיל» и «מרחק».
async function ageGeometry(page: Page): Promise<Geo> {
  return page.evaluate(() => {
    const leaves = [...document.querySelectorAll('div')].filter((d) => d.childElementCount === 0);
    const title = leaves.find((d) => d.textContent?.trim() === 'גיל')!;
    const next = leaves.find((d) => d.textContent?.trim() === 'מרחק')!;
    const y0 = title.getBoundingClientRect().bottom;
    const y1 = next.getBoundingClientRect().top;
    const nums = leaves
      .filter((d) => /^\d+\+?$/.test(d.textContent?.trim() ?? ''))
      .map((d) => ({ v: d.textContent!.trim(), r: d.getBoundingClientRect() }))
      .filter((o) => o.r.top > y0 && o.r.bottom < y1 && o.r.width > 0);
    const ticksTop = Math.max(...nums.map((o) => o.r.top));
    const ticks = nums.filter((o) => o.r.top >= ticksTop - 2);
    const labels = nums
      .filter((o) => o.r.top < ticksTop - 10)
      .map((o) => ({ v: o.v, x: o.r.x + o.r.width / 2, y: o.r.y + o.r.height / 2 }))
      .sort((a, b) => a.x - b.x);
    const cx = (v: string) => { const t = ticks.find((o) => o.v === v)!; return t.r.x + t.r.width / 2; };
    const labelBottom = Math.max(...nums.filter((o) => o.r.top < ticksTop - 10).map((o) => o.r.bottom));
    return { labels, x20: cx('20'), x60: cx('60+'), trackY: (labelBottom + ticksTop) / 2 };
  });
}

const num = (v: string) => (v === '60+' ? 60 : Number(v.replace('+', '')));

// Текущие значения ползунка возраста по меткам: [мин, макс] («60+» → 60). При мин = макс метка одна.
export async function ageValues(page: Page): Promise<[number, number]> {
  const g = await ageGeometry(page);
  expect(g.labels.length, 'метки над ручками возраста (1 при мин = макс, иначе 2)').toBeGreaterThanOrEqual(1);
  expect(g.labels.length).toBeLessThanOrEqual(2);
  const lo = num(g.labels[0].v);
  return [lo, g.labels.length === 2 ? num(g.labels[1].v) : lo];
}

// Метки над ручками не перекрываются (реджект 29.10).
export async function expectLabelsApart(page: Page) {
  const g = await ageGeometry(page);
  expect(g.labels).toHaveLength(2);
  // ширина метки ~36 px — центры должны отстоять хотя бы на ширину метки
  expect(g.labels[1].x - g.labels[0].x, 'метки «мин»/«макс» не наложены').toBeGreaterThanOrEqual(30);
}

// x центра ручки для значения v (шкала линейная: деление «20» … «60+»).
async function xOf(page: Page, v: number) {
  const g = await ageGeometry(page);
  return { x: g.x20 + ((v - 20) * (g.x60 - g.x20)) / 40, y: g.trackY };
}

// Нажать в центре ручки со значением from и тянуть до x (мышью, мелкими шагами).
export async function dragHandle(page: Page, from: number, toX: number) {
  const s = await xOf(page, from);
  await page.mouse.move(s.x, s.y);
  await page.mouse.down();
  await page.mouse.move(s.x + Math.sign(toX - s.x) * 4, s.y, { steps: 2 });
  await page.mouse.move(toX, s.y, { steps: 20 });
  await page.mouse.up();
}

// Тянуть ручку, пока её метка не станет target, и отпустить. Сначала рывок на 8 px (жесту нужен старт),
// затем шаги по 2 px в сторону цели (с возвратом, если проскочили).
export async function dragHandleTo(page: Page, which: 'min' | 'max', target: number) {
  const idx = which === 'min' ? 0 : 1;
  const from = (await ageValues(page))[idx];
  if (from === target) return;
  const s = await xOf(page, from);
  // Сразу после загрузки ползунок ещё не принимает жест (замер разметки) — повторяем захват, пока ручка не сдвинется.
  let x = s.x;
  await expect
    .poll(async () => {
      await page.mouse.move(s.x, s.y);
      await page.mouse.down();
      x = s.x + Math.sign(target - from) * 8;
      await page.mouse.move(x, s.y, { steps: 4 });
      const moved = (await ageValues(page))[idx] !== from;
      if (!moved) await page.mouse.up();
      return moved;
    }, { message: `ручка ${which} (${from}) не захватывается`, timeout: 10_000, intervals: [200, 300, 500] })
    .toBe(true);
  for (let i = 0; i < 300; i++) {
    const v = (await ageValues(page))[idx];
    if (v === target) break;
    x += Math.sign(target - v) * 2;
    await page.mouse.move(x, s.y);
  }
  await page.mouse.up();
  expect((await ageValues(page))[idx], `ручка ${which} → ${target}`).toBe(target);
}

// Края экрана для «тянуть до конца».
export const FAR_LEFT = 2;
export const farRight = (page: Page) => (page.viewportSize()?.width ?? 390) - 2;
